ValidationRule.errorConditionFormula:
AND(
NOT($Setup.Metadata_Activation_Settings__c.Disable_VR__c && OR(ISBLANK($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c),
CONTAINS($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c, 'Account'))),

/*---Block when Hierarchy Level is not Country Parent---*/
NOT( ISPICKVAL(IM_Hierarchy_Level__c,'Country Parent')),

/*---Block on create or when Industry Override is changed---*/
OR(
AND(
ISNEW(),
Industry_Override__c = True
),
AND(
ISCHANGED( Industry_Override__c )
)
),

$User.UITheme <>'Theme2',
$User.UITheme <> 'Theme3'

)
